        /// <summary>Basis for an element, falling back to Charge (the classic bulb) for
        /// a plant with no element -- a toy clone or a microscene release.</summary>
        public static float[][] For(CosmicShore.Data.Element element)
        {
            switch (element)
            {
                case CosmicShore.Data.Element.Charge: return Charge;
                case CosmicShore.Data.Element.Mass: return Mass;
                case CosmicShore.Data.Element.Space: return Space;
                case CosmicShore.Data.Element.Time: return Time;
                default: return Charge;
            }
        }
    }
